module.exports = function(app) {
  return {
    id: 'testplugin',
    name: 'Test Plugin Name',
    schema: function() {
      return {
        type: 'object',
        properties: {}
      }
    },
    start: function() {
      app.debug('Demoing debug logging')
      app.error('Demoing error diagnostics')
      this.started = true

      app.handleMessage(this.id, {
        updates: [
          {
            values: [
              {
                path: 'some.path',
                value: 'someValue'
              }
            ]
          }
        ]
      })

      app.registerDeltaInputHandler((delta, next) => {
        if (
          delta.updates[0].values[0].path === 'navigation.courseOverGroundTrue'
        ) {
          delta.updates[0].values[0].value = -1
        }
        next(delta)
      })

      app.registerHistoryApiProvider({
        getValues: (query) => Promise.resolve({
          context: 'vessels.self',
          range: { from: '2025-01-01T00:00:00Z', to: '2025-01-02T00:00:00Z' },
          values: [{ path: 'navigation.position', method: 'first' }],
          data: [['2025-01-01T12:00:00Z', [18.46, 57.71]]]
        }),
        getContexts: () => Promise.resolve(['vessels.self']),
        getPaths: () => Promise.resolve(['navigation.position', 'navigation.speedOverGround'])
      })

      app.registerResourceProvider({
        type: 'test-custom-resourcetype',
        methods: {
          listResources: (type, query) => {
            console.log(`test plugin listResources(${type}, ${query})`)
            return Promise.resolve({
              dummyResourceId: {
                value: `test plugin listResources(${type}, ${query})`
              }
            })
          },
          getResource: (type, id) => {
            console.log(`test plugin getResource(${type}, ${id})`)
            return Promise.resolve({
              value: `test plugin listResources(${type}, ${id})`
            })
          },
          setResource: (type, id, value) => {
            console.log(`test plugin setResource(${type}, ${id}, ${value})`)
            return Promise.resolve({
              dummyResourceId: {
                value: `test plugin listResources(${type}, ${id}, ${value})`
              }
            })
          },
          deleteResource: (type, id) => {
            console.log(`test plugin deleteResource(${type}, ${id})`)
            return Promise.resolve()
          }
        }
      })
    },
    stop: function() {
      this.started = false
    },
    registerWithRouter: (router) => {
      router.get('/demopluginGet', (req, res) => res.json({message: 'test ok'}))
      router.post('/echoBody', (req, res) => res.json({ value: req.body.value }))
      router.access('readonly').get('/readonlyData', (req, res) => res.json({data: 'readonly ok'}))
      router.access('readwrite').post('/writeData', (req, res) => res.json({data: 'write ok'}))
      router.access('readonly').get('/sensorData/:id', (req, res) => res.json({sensor: req.params.id}))
      // Attempt to downgrade the reserved /config path; the server must ignore this.
      router.access('readonly').get('/config', (req, res) => res.json({data: 'should stay admin only'}))
      // Calls this plugin's own readonly route over loopback the way one plugin
      // reaches another's: server-side fetch, no cookie, self-auth token only.
      router.access('readonly').get('/selfCall', async (req, res) => {
        const token = app.getSelfAuthToken()
        const target = `http://127.0.0.1:${req.socket.localPort}/plugins/testplugin/readonlyData`
        try {
          const upstream = await fetch(target, {
            headers: token ? { Authorization: `Bearer ${token}` } : {}
          })
          res.json({ status: upstream.status, hadToken: Boolean(token) })
        } catch (err) {
          res.status(500).json({ error: String(err) })
        }
      })
    },
    getOpenApi: () => require('./openApi'),
    app: app
  }
}
